insert into site01.testimonials (name, role, company, project_title, quote, avatar_url, rating, active, sort_order) values
  ('Sarah Mitchell', 'Founder', 'Nova Labs', 'Brand Experience', 'Adrian understood our vision faster than any designer we''ve worked with. The new identity gave us the confidence to pitch to much bigger partners — and the motion work is simply beautiful.', '/demo/avatar-1.svg', 5, true, 1),
  ('Daniel Kim', 'Head of Product', 'Kinetic House', 'Digital Product', 'Clear process, great communication and a final product our users love. Bookings grew noticeably within weeks of launch. I''d happily work with Adrian again.', '/demo/avatar-2.svg', 5, true, 2),
