insert into site01.blog_posts (title, slug, excerpt, content, cover_image_url, category, read_time, published_at, status) values
  ('Motion principles that make interfaces feel premium', 'motion-principles-premium-interfaces', 'Animation should explain, not decorate. Here are the five motion rules I use on every product.', 'Good motion is invisible. It answers questions before the user asks them: where did that come from, where did it go, what can I do next?

## 1. Motion supports hierarchy
The most important element should move first. Supporting content follows with a short stagger so the eye has a clear path.

## 2. Prefer transform and opacity
They are cheap for the browser to animate and keep scrolling smooth at 60fps, even on mid-range phones.

## 3. Respect reduced motion
Some people get dizzy from large movements. When the operating system asks for reduced motion, remove non-essential animation entirely.

## 4. Keep durations short
Most UI transitions feel best between 200ms and 500ms. Anything longer should be a deliberate storytelling moment.

## 5. Stop when the job is done
Non-stop animation competes with content. Let things settle so people can read.', '/demo/blog-motion-principles.svg', 'Motion', '4 min read', '2026-05-02', 'published'),
  ('Building a brand system that scales with your product', 'brand-system-that-scales', 'A logo is not a brand. How to design a flexible system that survives real-world use.', 'Most brands break the first time they meet a real product. The logo looks great on a poster, but nobody decided how buttons, charts or empty states should feel.

## Start with principles
Write three words that describe how the brand should feel. Every later decision gets tested against them.

## Design tokens first
Colour, type, spacing and radius should be defined as tokens so design and code share one source of truth.

## Test in context
Put the system into real screens early: a pricing table, an error message, a dark mode dashboard. Those are the moments that reveal gaps.', '/demo/blog-brand-systems.svg', 'Branding', '5 min read', '2026-03-18', 'published'),
  ('Using AI for product visuals without losing your style', 'ai-product-visuals-style', 'AI can speed up art direction — if you treat it like a junior assistant, not the designer.', 'AI image tools are fast, but speed without direction produces generic results. The trick is to keep the creative decisions human.

## Build a visual brief
Collect references, lighting notes and colour palettes before you write a single prompt.

## Iterate in small steps
Change one variable at a time so you learn what actually improves the image.

## Finish by hand
Retouch, colour-grade and composite the final images so they match the rest of the brand perfectly.', '/demo/blog-ai-visuals.svg', 'AI', '3 min read', '2026-01-09', 'published');

